create table if not exists public.controlled_substances_log(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,product_id bigint not null references public.products(id),stock_id bigint references public.stocks(id) on delete set null,prescription_id bigint references public.prescriptions(id) on delete set null,sale_id bigint references public.sales(id) on delete set null,action text not null,quantity integer not null,previous_balance integer,remaining_balance integer,patient_name text,patient_phone text,doctor_name text,doctor_license text,notes text,actor_user_id uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
alter table public.controlled_substances_log enable row level security; revoke all on public.controlled_substances_log from anon,authenticated; grant select,insert,update,delete on public.controlled_substances_log to authenticated;
create policy controlled_substances_log_tenant on public.controlled_substances_log for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_controlled_substance_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from products p where p.id=new.product_id and p.business_id=new.business_id) then raise exception 'product does not belong to business'; end if; if new.stock_id is not null and not exists(select 1 from stocks s where s.id=new.stock_id and s.business_id=new.business_id and s.product_id=new.product_id) then raise exception 'stock does not belong to business/product'; end if; if new.prescription_id is not null and not exists(select 1 from prescriptions p where p.id=new.prescription_id and p.business_id=new.business_id) then raise exception 'prescription does not belong to business'; end if; if new.sale_id is not null and not exists(select 1 from sales s where s.id=new.sale_id and s.business_id=new.business_id) then raise exception 'sale does not belong to business'; end if; if new.quantity<=0 then raise exception 'quantity must be positive'; end if; return new; end$$;
revoke all on function private.enforce_controlled_substance_business() from public,anon,authenticated;
create trigger trg_controlled_substance_business before insert or update on public.controlled_substances_log for each row execute function private.enforce_controlled_substance_business();